static BUKKIT_MATERIALS: LazyLock<HashSet<String>> = LazyLock::new(|| {
    serde_json::from_str::<Vec<String>>(BUKKIT_MATERIALS_JSON).expect("embedded data must parse")
        .into_iter()
        .collect()
});

/// Reproduces Nexo 1.26 `Material.matchMaterial` membership checks.
pub fn is_bukkit_material(name: &str) -> bool {
    BUKKIT_MATERIALS.contains(name)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn knows_common_materials() {
        // The locked legacy data table does not contain "stone"; membership
        // checks must stay in sync with legacy/src/materials-1.21.11.ts.
        assert!(is_bukkit_material("diamond_sword"));
        assert!(is_bukkit_material("paper"));
        assert!(!is_bukkit_material("not_a_material"));
    }
}
